const room = document.getElementById('fl');
{
  const h = room && room.closest('.hero');
  if (!h || !h.querySelector('.hero__inner') || !h.querySelector('.hero__copy')) {
    document.documentElement.classList.remove('hero-on');
    if (h) h.dataset.field = 'off';
    await new Promise(function () {});
  }
}
