    var s = new THREE.Mesh(strip, new THREE.MeshBasicMaterial({side: THREE.DoubleSide}));
    s.material.color.setScalar(30);
    s.position.set(x, .35, -1.2).normalize().multiplyScalar(12);
    s.lookAt(0, 0, 0);
    s.scale.set(3.2, 18, 1);
    room.add(s);
