  // candle so the light count never changes between one card's pass and
  // the next -- a different count would send every material back through
  // program selection on every pass. It is just turned off when the
  // product being drawn is not a lit candle.
  var flame = new THREE.PointLight(0xffa24a, 0, 190, 0);
